UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=59100, `VerifiedBuild`=19034 WHERE `ID` IN (9372 /*Demonic Contamination*/, 9701 /*Observing the Sporelings*/, 9708 /*Familiar Fungi*/, 9716 /*Disturbance at Umbrafen Lake*/, 9731 /*Drain Schematics*/, 9752 /*Escape from Umbrafen*/, 9968 /*Strange Energy*/, 9971 /*Clues in the Thicket*/, 10159 /*Keep Thornfang Hill Clear!*/, 10255 /*Testing the Antidote*/);
