UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=67500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12111 /*Where the Wild Things Roam*/, 12226 /*Just Passing Through*/);
