UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=4950, `VerifiedBuild`=19034 WHERE `ID` IN (12593 /*In Service Of The Lich King*/, 12670 /*The Scarlet Harvest*/, 12850 /*Report To Scourge Commander Thalanor*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='Well, $n, you''ve certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.$B$BDorian Drakestalker went north, across Bittertide Lake and established a camp there. He''s heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he''s had any luck.', `VerifiedBuild`=19034 WHERE `ID`=12595; -- In Search of Bigger Game
UPDATE `quest_template` SET `RewardXPDifficulty`=0, `RewardMoneyDifficulty`=2, `RewardBonusMoney`=0, `VerifiedBuild`=19034 WHERE `ID` IN (12597 /*Something for the Pain*/, 12599 /*Creature Comforts*/);
