UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='You''ve proved that you''re to be trusted and more.$B$BYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, $n.', `VerifiedBuild`=19034 WHERE `ID`=12768; -- The Steward of Wyrmrest Temple
