UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=27600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25400 /*The Gordunni Threat*/, 25451 /*Pristine Yeti Hide*/, 26401 /*Return to Vestia*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=48900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25421; -- The Grand Tablet
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `QuestDescription`='I thank you for freeing me, $n.  I will tell our allies of my findings.$B$BI suggest that you return to the emerald dragon that sent you.$B$BThe Twilight''s Hammer does not just seek to gain territory with this particular attack.  They''re also after a prisoner.$B$BFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.', `VerifiedBuild`=19034 WHERE `ID`=25424; -- Return to Alysra
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=24900, `VerifiedBuild`=19034 WHERE `ID` IN (25426 /*War on the Woodpaw*/, 25429 /*Zukk'ash Infestation*/, 25432 /*It's Not ""Ogre"" Yet*/, 25434 /*Taming The Tamers*/);
