UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=50700, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25695; -- Watching Our Back
