UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26173; -- Protecting Our Rear
