UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `Flags`=33558784, `RewardCurrencyID1`=81, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=26177; -- Feeling Crabby?
