UPDATE `quest_template` SET `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='These two have no idea how to tell a story.  Theldurin''s story was too short, and Lucien''s tale was a little too tall, if you catch my drift.$b$bAlso, neither of their stories had hot babes in them.$b$bSit back, $n.  I''ll tell you what really happened that day.', `VerifiedBuild`=19034 WHERE `ID`=27715; -- The Day that Deathwing Came: What Really Happened
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `Flags`=135266432, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27719; -- Water of Life
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AllowableRaces`=52430847, `QuestDescription`='Okay, $n, we need to get to the earth portal at the back of the cave.$B$BI''ve "procured" a ride for us. Why walk when we can ride in style? I hope you don''t mind mine carts.$B$BLet me know when you''re ready.', `VerifiedBuild`=19034 WHERE `ID` IN (27720 /*Mr. Goldmine's Wild Ride*/, 28885 /*Mr. Goldmine's Wild Ride*/);
