UPDATE `quest_template` SET `QuestPackageID`=602, `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28730; -- Precious Waters
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `Flags`=786432, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28734; -- A Favor for Melithar
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=82000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='It was an ambush, $n! As soon as we walked in a super-fat ogre named Rom''ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the "Chamber of Incineration." I think it''s just down the hall across the bridge.$B$BI''m too scared to go any further. Take my all-purpose diving helm and search for Raz. I''ll communicate with you through the helm.$B$BAnd if you find that ogre, kill him!', `VerifiedBuild`=19034 WHERE `ID`=28735; -- To the Chamber of Incineration!
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=82000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28737 /*What Is This Place?*/, 28741 /*Ascendant Lord Obsidius*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=82000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='<Finkle''s helm hums with energy.>$B$BDamn it! Raz won''t stop! It''s as if he were possessed with a burning vengeance for all things Twilight! It looks like if we''re going to get past this room and catch up with Raz we''ll need to take out the Twilight armorer, Karsh Steelbender. Kill him quick, $n.', `VerifiedBuild`=19034 WHERE `ID`=28738; -- The Twilight Forge
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=82000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='<Finkle''s helm explodes with the sound of a loud girlish scream.>$B$BIT CAN''T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren''t for my suit and the all-purpose helm I''d have died a fiery death! And look at that, it''s had a litter of pups!$B$BY... You gotta stop that thing, $n! We can''t let it or its pups make it out of here alive!', `VerifiedBuild`=19034 WHERE `ID`=28740; -- Do My Eyes Deceive Me?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=68400, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28742 /*Shy-Rotam*/, 28782 /*A Bird of Legend*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='You''re a pro at this, $n! A regular junior botanist! Listen, I''ve got a new seed to try called the rocknut. Use it to block the undead. Just drop it down and they''ll stop dead in their tracks. Undead are so stupid!$B$BLet''s give it a try!', `VerifiedBuild`=19034 WHERE `ID`=28744; -- Ghouls Hate My Grains
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=68400, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28745; -- Screechy Keen
