UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=4950, `Flags`=536870920, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28749; -- The Battle for Andorhal
