UPDATE `quest_template` SET `RewardBonusMoney`=6900, `Flags`=12, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=29392; -- Missing Heirlooms
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=960, `Flags`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=29400; -- A Season for Celebration
UPDATE `quest_template` SET `AllowableRaces`=18875469, `LogDescription`='Obtain 2 Strange Dust, 5 Crystal Vials, and 5 Blood Nettle.', `QuestDescription`='I''d be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn''t warn you of the danger?$B$BHere''s a better idea: let''s work together to recover the crate and ensure that its contents can''t hurt anyone. To protect ourselves, we''re going to need a draught made from a few ingredients that can be found around the city.$B$BAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.', `VerifiedBuild`=19034 WHERE `ID`=29402; -- Taking Precautions
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=29412; -- Blown Away
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `Flags`=12, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=29415; -- Missing Heirlooms
UPDATE `quest_template` SET `AllowableRaces`=33555378, `LogDescription`='Obtain 2 Strange Dust, 5 Crystal Vials, and 5 Blood Nettle.', `QuestDescription`='So someone else hired you to retrieve this crate? I don''t like the sound of that.$B$BThat crate''s contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous.$B$BWe have to find the meeting that Dran set up between the thief and the collector, but first, we''ll need to protect ourselves from the effects of handling that crate.$B$BAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.', `VerifiedBuild`=19034 WHERE `ID`=29426; -- Taking Precautions
UPDATE `quest_template` SET `LogDescription`='Kerri Hicks wants you to collect 250 Grisly Trophies.  Trophies are obtained as long as you kill creatures that offer experience or honor and you have the Darkmoon Adventurer''s Guide with you.', `VerifiedBuild`=19034 WHERE `ID`=29433; -- Test Your Strength
UPDATE `quest_template` SET `RewardItem1`=93724, `RewardAmount1`=1, `ItemDropQuantity2`=1, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `VerifiedBuild`=19034 WHERE `ID` IN (29434 /*Tonk Commander*/, 29436 /*The Humanoid Cannonball*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `AllowableRaces`=52430847, `QuestDescription`='Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure.$B$BWe can only conclude that the Twilight''s Hammer has gotten to her. You must confront her, $n. Destroy her if you must - I cannot bear to see it.$B$BShe was last seen in the Ruins of Lar''donir, west of the World Tree.', `VerifiedBuild`=19034 WHERE `ID`=29437; -- The Fallen Guardian
UPDATE `quest_template` SET `RewardItem1`=93724, `RewardAmount1`=1, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `VerifiedBuild`=19034 WHERE `ID` IN (29438 /*He Shoots, He Scores!*/, 29455 /*Target: Turtle*/, 29463 /*It's Hammer Time*/);
UPDATE `quest_template` SET `RewardBonusMoney`=38700, `AllowableRaces`=52430847, `QuestDescription`='The Earthen Ring calls to you once more, $n.$B$BAs a member of the Alliance, I know that you may have reservations working with the one you call Thrall, the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.$B$BCast aside your doubts, $c, and heed the world-shaman''s call.$B$BYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.', `VerifiedBuild`=19034 WHERE `ID`=29439; -- The Call of the World-Shaman
UPDATE `quest_template` SET `RewardBonusMoney`=38700, `AllowableRaces`=52430847, `QuestDescription`='The Earthen Ring calls to you once more, $n.$B$BThrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde''s finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.$B$BYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!', `VerifiedBuild`=19034 WHERE `ID`=29440; -- The Call of the World-Shaman
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID` IN (29443 /*A Curious Crystal*/, 29444 /*An Exotic Egg*/, 29445 /*An Intriguing Grimoire*/, 29446 /*A Wondrous Weapon*/, 29456 /*A Captured Banner*/, 29457 /*The Enemy's Insignia*/, 29458 /*The Captured Journal*/);
